int[] znajdzParę(int[] posortowana, int cel) {
    int lewy = 0, prawy = posortowana.length - 1;
    while (lewy < prawy) {
        int suma = posortowana[lewy] + posortowana[prawy];
        if (suma == cel) {
            return new int[] { posortowana[lewy], posortowana[prawy] };
        } else if (suma < cel) {
            lewy++;  // suma za mala - potrzeba wiekszej wartosci, przesun lewy w prawo
        } else {
            prawy--; // suma za duza - potrzeba mniejszej wartosci, przesun prawy w lewo
        }
    }
    return null; // brak pasujacej pary
}

int najwiekszaPojemnosc(int[] wysokosci) {
    int lewy = 0, prawy = wysokosci.length - 1;
    int najlepsza = 0;
    while (lewy < prawy) {
        int szerokosc = prawy - lewy;
        int wysokosc = Math.min(wysokosci[lewy], wysokosci[prawy]);
        najlepsza = Math.max(najlepsza, szerokosc * wysokosc);
        // przesuwamy ZAWSZE nizszy slupek - przesuniecie wyzszego nigdy nie moze poprawic wyniku
        if (wysokosci[lewy] < wysokosci[prawy]) lewy++; else prawy--;
    }
    return najlepsza;
}

